import{_ as r,o as t,c as i,a2 as a}from"./chunks/framework.Cxtv3Pj-.js";const d=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1785719861000}'),n={name:"guide/introduction.md"};function o(s,e,c,l,u,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="about-truelicense" tabindex="-1">About TrueLicense <a class="header-anchor" href="#about-truelicense" aria-label="Permalink to &quot;About TrueLicense&quot;">​</a></h2><p><a href="https://github.com/christian-schlichtherle/truelicense" target="_blank" rel="noreferrer">TrueLicense</a> is an open source engine for license management on the <abbr title="Java Virtual Machine">JVM</abbr>. Due to its functional and modular design, it scales from simple to complex licensing schemas.</p><p>TrueLicense features various interfaces for managing free trial periods, subscriptions, multiple editions, internationalization and more.</p><p>TrueLicense is designed with security in mind: Your intellectual property gets protected by digitally signing the license keys and obfuscating the string constants as well as the byte code of your software. The privacy of your customers gets protected by encrypting the license keys. The <abbr title="Application Programming Interface">API</abbr> lets you configure all the cryptographic standards implemented by the security providers which are installed in the <abbr title="Java Runtime Environment">JRE</abbr>.</p><p>TrueLicense requires a <abbr title="Java Runtime Environment">JRE</abbr>, version 1.8 or later.</p><h2 id="about-the-truelicense-maven-archetype" tabindex="-1">About The TrueLicense Maven Archetype <a class="header-anchor" href="#about-the-truelicense-maven-archetype" aria-label="Permalink to &quot;About The TrueLicense Maven Archetype&quot;">​</a></h2><p>The <a href="https://github.com/christian-schlichtherle/truelicense-maven-archetype" target="_blank" rel="noreferrer">TrueLicense Maven Archetype</a> is a <a href="https://maven.apache.org/guides/introduction/introduction-to-archetypes.html" target="_blank" rel="noreferrer">Maven Archetype</a> for generating licensing schemas. The Maven archetype generates a project containing separate modules for vending and consuming license keys. You can customize the project for your software product without writing code by <a href="/reference/config-properties">configuring its properties</a>.</p><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Generate a licensing schema without writing code.</li><li>Customize the licensing schema by configuring a set of properties.</li><li>Configure a free trial period for your users, called <em><abbr title="Free Trial Period">FTP</abbr></em>.</li><li>Sell different types of license keys for different feature sets of your software product, called <em>editions</em>.</li><li>Encode custom properties into license keys using JSON or XML.</li><li>Generate an <abbr title="Application Programming Interface">API</abbr> for vending and consuming license keys.</li><li>Generate a <abbr title="Command Line Interface">CLI</abbr> for vending and consuming license keys.</li><li>Generate a <abbr title="Graphical User Interface">GUI</abbr> for consuming license keys.</li><li>Generate a <abbr title="Representational State Transfer">ReST</abbr>-based <abbr title="Web Service Interface">WSI</abbr> for consuming license keys.</li><li>Use the TrueLicense Maven Plugin to obfuscate string constants.</li><li>Assemble all dependencies into a standalone <abbr title="Java ARchive">JAR</abbr>.</li><li>Use ProGuard to obfuscate the standalone <abbr title="Java ARchive">JAR</abbr> into a guarded <abbr title="Java ARchive">JAR</abbr>.</li><li>Use Git or Mercurial as your <abbr title="Version Control System">VCS</abbr>.</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Before version 4, TrueLicense and the TrueLicense Maven Archetype were covered by the <abbr title="GNU&#39;s Not Unix">GNU</abbr> Affero General Public License, Version 3. Since version 4, TrueLicense is covered by the <a href="https://github.com/christian-schlichtherle/truelicense/blob/HEAD/LICENSE" target="_blank" rel="noreferrer">Apache License 2.0</a>, and the TrueLicense Maven Archetype is covered by the <a href="https://github.com/christian-schlichtherle/truelicense-maven-archetype/blob/HEAD/LICENSE" target="_blank" rel="noreferrer">MIT License</a>.</p>',12)])])}const p=r(n,[["render",o]]);export{d as __pageData,p as default};
